// export default Hero;
import React from "react";

const Hero = () => {
  return (
    <div className="px-6">
      {/* Top text section */}
      <div className="text-center mt-5 mb-5">
        <h1 className="text-3xl font-bold mb-2">Open a free demat & trading account online</h1>
        <p className="text-gray-600 font-semibold">
          Start investing brokerage free and join a community of 1.5+ crore
          investors and traders
        </p>
      </div>

      {/* Flex section */}
      <div className="flex flex-col md:flex-row items-center gap-8">
        {/* Image */}
        <div className="md:w-1/3 w-1/2">
          <img src="assets/signup.svg" alt="Signup" className="w-full" />
        </div>

        {/* Form */}
        <div className="md:w-2/3 w-full">
          <h1 className="text-2xl font-bold mb-2">Signup now</h1>
          <h3 className="text-lg text-gray-600 mb-4">Or track your existing application</h3>
          <input
            type="text"
            className="border border-gray-300 p-2 rounded w-full"
            placeholder="Enter your mobile number"
          />
        </div>
      </div>
    </div>
  );
};

export default Hero;
